// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testRegression_property() public {
        address[] memory tos = new address[](4);
        tos[0] = address(0x100);
        tos[1] = address(0x200);
        tos[2] = address(0x300);
        tos[3] = address(0x400);
        Token token = new Token();
        token.mint(address(this), 1000);
        token.approve(address(c), 1000);
        c.transfer(address(this), address(token), tos, 10);
        uint256 balanceOfIndex1 = token.balanceOf(tos[1]);
        assertTrue(balanceOfIndex1 == 10, "Index 1 should have received tokens");
    }
}

contract Token {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) public {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
